CreateIngressGateway.input:
POST / HTTP/1.1
Host: tcm.tencentcloudapi.com
Content-Type: application/json
X-TC-Action: CreateIngressGateway
<公共请求参数>

{
    "Workload": {
        "SelectedNodeList": [
            "10.0.0.2"
        ],
        "HorizontalPodAutoscaler": {
            "MinReplicas": 1,
            "Metrics": [
                {
                    "Pods": {
                        "TargetAverageValue": "80",
                        "MetricName": "k8s_pod_rate_cpu_core_used_request"
                    },
                    "Type": "Pods"
                }
            ],
            "MaxReplicas": 3
        },
        "Resources": {
            "Requests": [
                {
                    "Name": "cpu",
                    "Quantity": "1"
                }
            ],
            "Limits": [
                {
                    "Name": "cpu",
                    "Quantity": "2"
                }
            ]
        },
        "Replicas": 1
    },
    "Name": "istio-ingressgateway",
    "Service": {
        "ExternalTrafficPolicy": "Cluster",
        "Type": "LoadBalancer",
        "CLBDirectAccess": true
    },
    "ClusterId": "cls-xxxxxxxx",
    "Namespace": "istio-system",
    "MeshId": "mesh-xxxxxxxx",
    "LoadBalancer": {
        "LoadBalancerType": "OPEN"
    }
}

